		+ texture2D( tBloom, vUv + d ).rgb + texture2D( tBloom, vUv - d ).rgb + texture2D( tBloom, vUv + vec2( d.x, - d.y ) ).rgb + texture2D( tBloom, vUv + vec2( - d.x, d.y ) ).rgb;
