  const depthU = { tDepth: { value: depthTexture }, uProj: { value: new THREE.Vector4() }, uZ: { value: new THREE.Vector3() } };
  const resU = { value: new THREE.Vector2(1, 1) }, invResU = { value: new THREE.Vector2(1, 1) };

