                if ((ci === 0 && ei === C.longest) || C.edges[ei].l < 2.4) continue;
                const kind = wallKinds[Math.floor(hq(h, 603 + ci * 40 + e * 5) * wallKinds.length)], depth = kind === 'bench' ? 0.03 : kind === 'pithoi' ? 0.32 : kind === 'tools' ? 0.22 : 0.45;
