    const doorsNear = (x, z, r) => { for (const q of layout.housesNear(x, z, r + 6)) { if (!q.door) continue; const d = Math.hypot(q.door[0] - x, q.door[1] - z); if (d < r || (d < 4.4 && hq(q, 207) < 0.33)) return true; } return false; };
