    for (let i = 0; i < 3; i++) vessel(b, 'ovoid', w * 0.12 + 0.24 * i - 0.1, d * 0.25, 0.45, lod, [P.clayBuff, P.clayPale, P.clayRed][i], { lid: P.woolOatmeal });
