      T.quadF(cedar, f.P(s - 0.6, 0.41, F), f.P(s + 0.6, 0.41, F), f.P(s + 0.6, 0.41, F + 2.4), f.P(s - 0.6, 0.41, F + 2.4), f.nx, 0, f.nz);
