    const c0 = M.openRing(M.rectRing(...M.localToWorld([h.x, h.z], rotE, 0, -8.5), 5.2, 9, rotE)), c1 = M.openRing(M.rectRing(...M.localToWorld([h.x, h.z], rotE, 0.6, 9), 6, 8, rotE));
