      const gh = layout.houses.find((h) => h.landmark && M.pointInPolygon(P8.pos[0], P8.pos[2], h.footprint)) || (typeof layout.houseAt === 'function' ? layout.houseAt(P8.pos[0], P8.pos[2]) : null);
