        s0 = wisp ? 0.16 : 0.42 * size + 0.22; s1 = wisp ? 1.0 + 0.5 * h3 : (6.0 + 3.2 * h3) * Math.pow(size, 0.7);
        alpha = (wisp ? 0.17 : 0.34) * M.clamp(size + 0.25, 0.55, 1.1);
