              const off = [-1.3, -0.1, 1.2, 2.6][row] + (hash2(k2, row, seed + 4) - 0.5) * 0.9, sl = (hash2(k2, row, seed + 6) - 0.5) * 1.2;
              const x = x0 + nx * off + tx * sl, z = z0 + nz * off + tz * sl, y = ground.height(x, z);
